(function(){
  CardSpoke_MODS.register('narrative-guards', {
    meta: {
      name: 'Narrative Guards',
      type: 'Mod',
      version: '1.0.0',
      creator: 'CardSpoke Team',
      description: 'Prevents deleting storyline cards that have threads attached',
      releaseDate: '2024-10-20',
      source: 'official'
    },
    onCardDelete(ctx, card){
      if(card && Array.isArray(card.children) && card.children.length){
        ctx.api.showToast('Keep threads intact: unlink children first.', 'error');
        return false;
      }
    },
    onDisable(){ /* behavioral mod only */ }
  });
})();
